//MethodTemplateName=CSharpInOut;
IDisposable elevatedIdentityScope = null;

try
{
	if (!CCO.Permissions.UserHasRootOrAdminIdentity())
	{
		Aras.Server.Security.Identity workflowManager = Aras.Server.Security.Identity.GetByName("Workflow Manager");
		elevatedIdentityScope = CCO.Permissions.GrantIdentity(workflowManager);
	}

	eventData.BaseLockItem(outDom);
}
finally
{
	elevatedIdentityScope?.Dispose();
}
